import axios from 'axios';

// Base URL for our API
const API_URL = 'http://localhost:8000/api';

// Set up axios instance with base URL
const api = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Add auth token to requests if available
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Auth service functions
const authService = {
  // Register new user
  register: async (userData) => {
    try {
      const response = await api.post('/auth/register', userData);
      
      if (response.data.access_token) {
        localStorage.setItem('token', response.data.access_token);
        // Since our backend doesn't return the user, we'll create a simplified user object
        const user = {
          username: userData.username,
          email: userData.email,
          full_name: userData.full_name
        };
        localStorage.setItem('user', JSON.stringify(user));
      }
      
      return {
        token: response.data.access_token,
        user: {
          username: userData.username,
          email: userData.email,
          full_name: userData.full_name
        }
      };
    } catch (error) {
      console.error('Registration error:', error.response);
      
      // Handle validation errors (422 Unprocessable Entity)
      if (error.response?.status === 422) {
        const validationErrors = error.response.data?.detail || [];
        
        // Format validation errors into readable messages
        let errorMessage = 'Validation failed: ';
        if (Array.isArray(validationErrors)) {
          errorMessage += validationErrors.map(err => {
            return `${err.loc[err.loc.length-1]}: ${err.msg}`;
          }).join(', ');
        } else {
          errorMessage += 'Please check your input and try again';
        }
        
        throw new Error(errorMessage);
      }
      
      throw error;
    }
  },
  
  // Login user
  login: async (credentials) => {
    try {
      // Convert our credentials to form data format expected by OAuth2 login endpoint
      const formData = new FormData();
      formData.append('username', credentials.username);
      formData.append('password', credentials.password);
      
      // OAuth2 endpoints expect form data, not JSON
      const response = await axios.post(
        `${API_URL}/auth/login`, 
        formData,
        {
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
          },
        }
      );
      
      if (response.data.access_token) {
        localStorage.setItem('token', response.data.access_token);
        
        // Get user profile with the new token
        try {
          const userResponse = await api.get('/auth/me', {
            headers: {
              Authorization: `Bearer ${response.data.access_token}`
            }
          });
          
          localStorage.setItem('user', JSON.stringify(userResponse.data));
          
          return {
            token: response.data.access_token,
            user: userResponse.data
          };
        } catch (profileError) {
          console.error('Error fetching user profile:', profileError);
          // Return just the token if profile fetch fails
          return {
            token: response.data.access_token,
            user: { username: credentials.username }
          };
        }
      }
      
      return response.data;
    } catch (error) {
      console.error('Login error:', error.response);
      
      if (error.response?.status === 401) {
        throw new Error('Invalid username or password');
      }
      
      throw error;
    }
  },
  
  // Logout user
  logout: () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
  },
  
  // Get current user
  getCurrentUser: () => {
    const user = localStorage.getItem('user');
    return user ? JSON.parse(user) : null;
  },
  
  // Update user profile
  updateProfile: async (userData) => {
    const response = await api.put('/auth/profile', userData);
    
    if (response.data.user) {
      localStorage.setItem('user', JSON.stringify(response.data.user));
    }
    
    return response.data;
  },
  
  // Check if token is still valid
  validateToken: async () => {
    try {
      const response = await api.post('/auth/validate');
      return response.data;
    } catch (error) {
      // If token validation fails, log the user out
      authService.logout();
      throw error;
    }
  }
};

export default authService;
